            # Geometric tile patterns encode a straight path segment.
            mask = tuple(tuple(int(grid[r0 + dr][c0 + dc] != 0) for dc in range(3)) for dr in range(3))
            if mask == ((1, 1, 0), (1, 0, 1), (0, 1, 0)):
                direction, length = 'R', 3
            elif mask == ((1, 0, 1), (1, 0, 1), (1, 1, 1)):
                direction, length = 'L', 2
            elif mask == ((1, 0, 1), (0, 1, 0), (0, 1, 0)):
                direction, length = 'D', 2
            elif mask == ((1, 1, 1), (0, 1, 0), (1, 0, 1)):
                direction, length = 'L', 4
            else:
                continue
            panels.append((c0, r0, color, direction, length))
    # Column-major reading order: all left panels from top to bottom, then right.
    panels.sort(key=lambda x: (x[0], x[1]))
    out = [[0 for _ in range(7)] for _ in range(h)]
    # Keep the red start marker in the cropped canvas.
    for r in range(h):
        for c in range(8, min(w, 15)):
            if grid[r][c] == 5:
                out[r][c - 8] = 5
                row, col = r, c - 8
                break
        else:
            continue
        break
    else:
        row, col = 0, 0
    for _, _, color, direction, length in panels:
        row += 1
        if direction == 'R':
            coords = [(row, col + i) for i in range(length)]
            col += length - 1
        elif direction == 'L':
            coords = [(row, col - i) for i in range(length)]
            col -= length - 1
        else:  # down
            coords = [(row + i, col) for i in range(length)]
            row += length - 1
        for rr, cc in coords:
            if 0 <= rr < h and 0 <= cc < 7:
                out[rr][cc] = color
    return out
